"""Triton implementation of upsample_nearest3d_backward (gather formulation).

Semantics reproduced from ATen (align_corners=False, nearest, NOT nearest-exact):

    scale_d = 1/scales_d   (when scales_d is not None and > 0)
            = ID/OD        (otherwise)                       -- float32
    src(x)  = min( int32(floorf(f32(x) * scale)), IN - 1 )
    grad_input[n, c, i, j, k] = sum_{dst : src(dst) == (i,j,k)} grad_output[n, c, dst]

Two device paths, chosen from host-side metadata only:

* ``_box_sum_kernel`` (fast path).  Used when, for every axis, ``out == in * r``
  with ``r`` a power of two and the float32 reciprocal scale is exactly ``1/r``
  (so ``floorf(x * s) == x // r`` exactly and the ``IN-1`` clamp can never
  fire).  The preimage of the box is then a regular ``r_d x r_h x r_w`` block,
  so grad_output can be read with large contiguous DMA tiles and folded with
  in-register reductions.
* ``_upsample_nearest3d_backward_kernel`` (general path).  Exact preimage
  intervals computed with the same float32 arithmetic as ATen; correct for any
  scale/size combination (down-sampling, non-integer ratios, clamp-active
  scales).

Both paths are input-major (one owner per grad_input element), so no atomics
and no zero-fill pass are needed; empty preimages naturally yield 0.0.  All
index math is float32, matching ATen's accscalar_t, and all accumulation is
float32 with a single cast on store.
"""

import struct

import torch
import triton
import triton.language as tl


@triton.jit
def _nearest_lower_bound(w, s, out_n):
    """Smallest ow in [0, out_n] with floor32(f32(ow) * s) >= w.

    `out_n` is also the exclusive upper bound of valid output indices, so the
    result is capped there (an empty preimage then yields lo == out_n).  The
    predicate is monotone in ow, so a couple of local corrections around the
    float candidate are exact.
    """
    wf = w.to(tl.float32)
    c = (wf / s).to(tl.int32)
    c = tl.minimum(tl.maximum(c, 0), out_n)
    for _ in tl.static_range(2):
        step = (((c - 1).to(tl.float32) * s) >= wf) & (c > 0)
        c = tl.where(step, c - 1, c)
    for _ in tl.static_range(2):
        step = ((c.to(tl.float32) * s) < wf) & (c < out_n)
        c = tl.where(step, c + 1, c)
    return c


@triton.jit
def _box_sum_kernel(
    go_ptr,
    gi_ptr,
    ID,
    IH,
    IW,
    OD,
    OH,
    OW,
    RD: tl.constexpr,
    RH: tl.constexpr,
    RW: tl.constexpr,
    C: tl.constexpr,
    CR: tl.constexpr,
    JH: tl.constexpr,
    PADDED: tl.constexpr,
    NUMEL,
):
    """One program per JH input rows; grad_output rows are read contiguously.

    For the regular case the r_w output columns of an input column are
    adjacent in memory, so a whole output row is one contiguous chunk; rows
    and r_d slices are summed in fp32 first and folded once at the end, so the
    inner body stays a plain vector add.  Every loop factor is
    constexpr-unrolled and each program owns JH rows, which keeps many
    independent GM reads in flight.

    When OW is not a power of two the row block is padded to C = next_pow2(OW)
    lanes.  Rather than paying a partially-masked load on every row, the read
    is issued unmasked (the padding lanes touch the following rows, which is
    harmless) and the padding is zeroed afterwards; only the very last row of
    the tensor, whose read would leave the buffer, falls back to a masked
    load.
    """
    i = tl.program_id(0)
    jb = tl.program_id(1)
    nc = tl.program_id(2)
    j0 = jb * JH

    cols = tl.arange(0, C)
    cmask = cols < OW
    iw = tl.arange(0, CR)
    iwm = iw < IW

    for jj in tl.static_range(JH):
        j = j0 + jj
        acc = tl.zeros((C,), dtype=tl.float32)
        for a in tl.static_range(RD):
            for b in tl.static_range(RH):
                base = ((nc * OD + i * RD + a) * OH + j * RH + b) * OW
                if base + C <= NUMEL:
                    v = tl.load(go_ptr + base + cols)
                else:
                    v = tl.load(go_ptr + base + cols, mask=cmask, other=0.0)
                if PADDED:
                    v = tl.where(cmask, v, 0.0)
                acc += v.to(tl.float32)
        res = tl.sum(tl.reshape(acc, (CR, RW)), axis=1)
        off = ((nc * ID + i) * IH + j) * IW + iw
        tl.store(gi_ptr + off, res.to(gi_ptr.dtype.element_ty), mask=iwm)


@triton.jit
def _upsample_nearest3d_backward_kernel(
    go_ptr,
    gi_ptr,
    s_d,
    s_h,
    s_w,
    ID,
    IH,
    IW,
    OD,
    OH,
    OW,
    MAXW: tl.constexpr,
    BLOCK_W: tl.constexpr,
    WBLOCKS: tl.constexpr,
):
    i = tl.program_id(0)  # input depth index
    j = tl.program_id(1)  # input height index
    nc = tl.program_id(2)  # fused batch/channel index

    s_d = s_d.to(tl.float32)
    s_h = s_h.to(tl.float32)
    s_w = s_w.to(tl.float32)

    od_lo = _nearest_lower_bound(i, s_d, OD)
    od_hi = tl.where(i < ID - 1, _nearest_lower_bound(i + 1, s_d, OD) - 1, OD - 1)
    od_hi = tl.minimum(od_hi, OD - 1)

    oh_lo = _nearest_lower_bound(j, s_h, OH)
    oh_hi = tl.where(j < IH - 1, _nearest_lower_bound(j + 1, s_h, OH) - 1, OH - 1)
    oh_hi = tl.minimum(oh_hi, OH - 1)

    for wb in tl.static_range(WBLOCKS):
        w = wb * BLOCK_W + tl.arange(0, BLOCK_W)
        wm = w < IW

        lo = _nearest_lower_bound(w, s_w, OW)
        hi = tl.where(w < IW - 1, _nearest_lower_bound(w + 1, s_w, OW) - 1, OW - 1)
        hi = tl.minimum(hi, OW - 1)
        cnt = hi - lo + 1

        acc = tl.zeros((BLOCK_W,), dtype=tl.float32)
        for od in range(od_lo, od_hi + 1):
            for oh in range(oh_lo, oh_hi + 1):
                base = ((nc * OD + od) * OH + oh) * OW
                for k in tl.static_range(MAXW):
                    ow = lo + k
                    m = wm & (k < cnt)
                    acc += tl.load(go_ptr + base + ow, mask=m, other=0.0)

        off = ((nc * ID + i) * IH + j) * IW + w
        tl.store(gi_ptr + off, acc.to(gi_ptr.dtype.element_ty), mask=wm)


def _f32(x):
    return struct.unpack("<f", struct.pack("<f", float(x)))[0]


def _reciprocal(scale, in_size, out_size):
    """ATen: 1/scale when scale is given and > 0, else in/out (in float32)."""
    if scale is not None and float(scale) > 0.0:
        return float(1.0 / float(scale))
    return float(in_size) / float(out_size)


def _max_per_input(o, i, r):
    """Upper bound on the number of output positions that map to one input."""
    base = int(1.0 / r) + 3 if r > 0.0 else o
    # When floor((o-1)*r) can reach i-1 the min(., i-1) clamp hands the whole
    # tail of the axis to the last input index.
    if i > 0 and float(o - 1) * r >= float(i - 1) - 1.0:
        tail = int(float(o) - float(i - 1) / r) + 3
        if tail > base:
            base = tail
    return max(base, 1)


def _fold_ratio(in_n, out_n, s):
    """Power-of-two r with out == in*r and float32(scale) == 1/r exactly."""
    if in_n <= 0 or out_n <= 0 or out_n % in_n != 0:
        return 0
    r = out_n // in_n
    if r & (r - 1):
        return 0
    if _f32(s) != _f32(1.0 / r):
        return 0
    return r


def upsample_nearest3d_backward(
    grad_output,
    output_size,
    input_size,
    scales_d=None,
    scales_h=None,
    scales_w=None,
):
    OD = int(output_size[0])
    OH = int(output_size[1])
    OW = int(output_size[2])
    N = int(input_size[0])
    C = int(input_size[1])
    ID = int(input_size[2])
    IH = int(input_size[3])
    IW = int(input_size[4])

    out = torch.empty(
        (N, C, ID, IH, IW), dtype=grad_output.dtype, device=grad_output.device
    )
    if N * C * ID * IH * IW == 0:
        return out
    if OD <= 0 or OH <= 0 or OW <= 0:
        return torch.zeros(
            (N, C, ID, IH, IW), dtype=grad_output.dtype, device=grad_output.device
        )

    r_d = _reciprocal(scales_d, ID, OD)
    r_h = _reciprocal(scales_h, IH, OH)
    r_w = _reciprocal(scales_w, IW, OW)

    rd = _fold_ratio(ID, OD, r_d)
    rh = _fold_ratio(IH, OH, r_h)
    rw = _fold_ratio(IW, OW, r_w)
    c = triton.next_power_of_2(OW)

    if rd and rh and rw and c <= 2048:
        # Rows per program only pays off while enough programs remain to fill
        # the device; tiny problems keep one row per program.
        jh = 1
        if ID * IH * N * C >= 2048:
            while jh * 2 <= 4 and IH % (jh * 2) == 0:
                jh *= 2
        grid = (ID, (IH + jh - 1) // jh, N * C)
        _box_sum_kernel[grid](
            grad_output,
            out,
            ID,
            IH,
            IW,
            OD,
            OH,
            OW,
            RD=rd,
            RH=rh,
            RW=rw,
            C=c,
            CR=c // rw,
            JH=jh,
            PADDED=c > OW,
            NUMEL=N * C * OD * OH * OW,
        )
        return out

    block_w = min(max(triton.next_power_of_2(IW), 8), 512)
    wblocks = (IW + block_w - 1) // block_w
    maxw = _max_per_input(OW, IW, r_w)

    grid = (ID, IH, N * C)
    _upsample_nearest3d_backward_kernel[grid](
        grad_output,
        out,
        r_d,
        r_h,
        r_w,
        ID,
        IH,
        IW,
        OD,
        OH,
        OW,
        MAXW=maxw,
        BLOCK_W=block_w,
        WBLOCKS=wblocks,
    )
    return out
